// ============================================================================
// CONFIGURATION — Populated from env at request time
// ============================================================================
const CONFIG = {
  DEEPSEEK_API_KEY: '',
  TAVILY_API_KEY: '',
  DEEPSEEK_MODEL: 'deepseek-v4-flash',
};

function initWithEnv(env) {
  if (env.DEEPSEEK_API_KEY) CONFIG.DEEPSEEK_API_KEY = env.DEEPSEEK_API_KEY;
  if (env.TAVILY_API_KEY)   CONFIG.TAVILY_API_KEY   = env.TAVILY_API_KEY;
  if (env.GROQ_API_KEY)     CONFIG.GROQ_API_KEY     = env.GROQ_API_KEY;
  if (env.GROQ_MODEL)       CONFIG.GROQ_MODEL       = env.GROQ_MODEL;
  console.log(`[Fathom boot] DEEPSEEK=${!!CONFIG.DEEPSEEK_API_KEY}(${(CONFIG.DEEPSEEK_API_KEY||'').length}) TAVILY=${!!CONFIG.TAVILY_API_KEY}(${(CONFIG.TAVILY_API_KEY||'').length}) GROQ=${!!CONFIG.GROQ_API_KEY} model=${CONFIG.GROQ_MODEL||'(default)'}`);
}

// ============================================================================
// DEEPSEEK API — OpenAI endpoint (for Agent A)
// ============================================================================
function parseJSON(text) {
  if (!text || typeof text !== 'string') return {};
  let s = text.trim();
  // Remove markdown fences
  s = s.replace(/^```(?:json)?\s*\n?/i, '').replace(/\n?```\s*$/i, '');
  // Find first { or [
  let i = s.search(/[\{\[]/);
  if (i >= 0) s = s.substring(i);
  // Find last } or ] and strip trailing text/whitespace
  let lastBrace = s.lastIndexOf('}');
  let lastBracket = s.lastIndexOf(']');
  let end = Math.max(lastBrace, lastBracket);
  if (end > 0) s = s.substring(0, end + 1);
  // Remove trailing commas before } or ]
  s = s.replace(/,\s*([\}\]])/g, '$1');
  // Try to parse
  try { return JSON.parse(s); } catch(e) {
    // Last resort: try to fix common issues
    try {
      s = s.replace(/\\'/g, "'");
      s = s.replace(/'([^']*?)'\s*:/g, '"$1":');
      // Also fix unescaped quotes inside string values
      s = s.replace(/:\s*"([^"]*?)"/g, function(m) { return m; }); // keep valid
      return JSON.parse(s);
    } catch(e2) {
      // Partial extraction: build minimal valid JSON
      const extractStr = (key) => {
        const m = text.match(new RegExp('"' + key + '"\\s*:\\s*"((?:[^"\\\\]|\\\\.)*)"', 'i'));
        return m ? m[1].replace(/\\n/g, '\n').replace(/\\"/g, '"') : null;
      };

      const extractArr = (key) => {
        // Find array for this key
        const arrRegex = new RegExp('"' + key + '"\\s*:\\s*\\[([\\s\\S]*?)\\](?=\\s*[,}])', 'i');
        const m = text.match(arrRegex);
        if (!m) return null;
        const arrContent = m[1];
        const items = [];
        // Extract each object in the array
        const objRegex = /\{([^{}]*(?:\{[^{}]*\}[^{}]*)*)\}/g;
        let objMatch;
        while ((objMatch = objRegex.exec(arrContent)) !== null) {
          try {
            const objStr = objMatch[0].replace(/,\s*\}/g, '}');
            items.push(JSON.parse(objStr));
          } catch(e) {}
        }
        return items.length > 0 ? items : null;
      };

      const extractObj = (key) => {
        const objRegex = new RegExp('"' + key + '"\\s*:\\s*(\\{[^{}]*(?:\\{[^{}]*\\}[^{}]*)*\\})', 'i');
        const m = text.match(objRegex);
        if (!m) return null;
        try {
          return JSON.parse(m[1].replace(/,\s*\}/g, '}'));
        } catch(e) {
          // Fallback: extract individual fields from nested object
          const sub = {};
          const fieldRegex = /"(\w+)"\s*:\s*"((?:[^"\\]|\\.)*)"/g;
          let fm;
          const searchText = m[1];
          while ((fm = fieldRegex.exec(searchText)) !== null) {
            sub[fm[1]] = fm[2].replace(/\\n/g, '\n').replace(/\\"/g, '"');
          }
          return Object.keys(sub).length > 0 ? sub : null;
        }
      };

      const partial = {};
      const strFields = ['briefing_en','briefing_zh','cultural_insight_en','cultural_insight_zh',
        'industry_notes_en','industry_notes_zh','scene_confirmation_en','scene_confirmation_zh'];
      for (const f of strFields) { const v = extractStr(f); if (v) partial[f] = v; }

      const arrFields = ['taboos','dos','risks'];
      for (const f of arrFields) { const v = extractArr(f); if (v) partial[f] = v; }

      const objFields = ['opening','strategy','deliverable'];
      for (const f of objFields) { const v = extractObj(f); if (v) partial[f] = v; }

      if (Object.keys(partial).length > 0) return { analysis: partial };
      console.error(`parseJSON failed. raw[0..200]: ${text.substring(0, 200)}`);
      return {};
    }
  }
}

// Parse structured Markdown → same {analysis:{}} format frontend expects
function parseMarkdownAnalysis(text) {
  if (!text || typeof text !== 'string') return {};
  text = text.replace(/```markdown\n?|```\n?/g, ''); // strip code fences
  const analysis = {};
  const sections = text.split(/\n##\s+/);
  
  for (const section of sections) {
    const nl = section.indexOf('\n');
    const header = (nl > 0 ? section.slice(0, nl) : section).toLowerCase().trim();
    const body = nl > 0 ? section.slice(nl + 1).trim() : '';
    if (!header || header.length > 60) continue;

    // Match by keywords — very lenient
    if (matchAny(header, ['核心洞察','core insight','executive briefing','executive summary','briefing','核心观察']))
      { analysis.briefing_zh = body; analysis.briefing_en = body; }
    else if (matchAny(header, ['开场','opening','greeting','问候','hello']))
      parseOpening(analysis, body);
    else if (matchAny(header, ['行业','industry','产业','market']))
      { analysis.industry_notes_zh = body; analysis.industry_notes_en = body; }
    else if (matchAny(header, ['场景','scene','confirm','确认','理解']))
      { analysis.scene_confirmation_zh = body; analysis.scene_confirmation_en = body; }
    else if (matchAny(header, ['注意','taboo','禁忌','避免','watch out','don','warning','caution']))
      { analysis.taboos = parseBullets(body); }
    else if (matchAny(header, ['应该','what to do','do:','recommend','建议','做法']))
      { analysis.dos = parseBullets(body); }
    else if (matchAny(header, ['战略','strateg','guidance','approach','指引']))
      parseStrategy(analysis, body);
    else if (matchAny(header, ['洞察','insight','反思','reflection']))
      { analysis.cultural_insight_zh = body; analysis.cultural_insight_en = body; }
    else if (matchAny(header, ['风险','risk']))
      { analysis.risks = parseRisks(body); }
    else if (matchAny(header, ['交付','deliver','template','邮件','email','script','agenda','模板','脚本']))
      parseDeliverable(analysis, body);
  }
  
  return (analysis.briefing_en || analysis.briefing_zh) ? { analysis } : {};
}

function matchAny(header, keywords) {
  return keywords.some(k => header.includes(k));
}

function parseOpening(analysis, body) {
  const op = {};
  const lines = body.split('\n');
  for (const line of lines) {
    const m = line.match(/^(?:\*\*)?(?:原文|native|本地)[：:]?\s*(?:\*\*)?\s*(.+)/i);
    if (m) { op.native = m[1].replace(/\*+/g, '').trim(); continue; }
    const m2 = line.match(/^(?:\*\*)?(?:翻译|english?|英文)[：:]?\s*(?:\*\*)?\s*(.+)/i);
    if (m2) { op.english = m2[1].replace(/\*+/g, '').trim(); continue; }
    const m3 = line.match(/^(?:\*\*)?(?:中文|chinese|用法|使用|context)[：:]?\s*(?:\*\*)?\s*(.+)/i);
    if (m3) { op.chinese = m3[1].replace(/\*+/g, '').trim(); continue; }
  }
  if (!op.english && !op.chinese && body.length < 500) op.native = body;
  analysis.opening = op;
}

function parseBullets(body) {
  const items = [];
  const lines = body.split('\n');
  for (const line of lines) {
    const trimmed = line.replace(/^[\s\-•*]+/, '').trim();
    if (!trimmed || trimmed.length < 5) continue;
    const dashIdx = Math.max(trimmed.indexOf(' — '), trimmed.indexOf(' - '), trimmed.indexOf('  '));
    const item = dashIdx > 0 ? trimmed.slice(0, dashIdx).trim().replace(/\*+/g, '') : trimmed.replace(/\*+/g, '');
    const why = dashIdx > 0 ? trimmed.slice(dashIdx + 3).trim().replace(/\*+/g, '') : '';
    items.push({ item_en: item, item_zh: item, why_en: why, why_zh: why });
  }
  return items;
}

function parseStrategy(analysis, body) {
  const strat = {};
  const lines = body.split('\n');
  let cur = '';
  for (const line of lines) {
    const m = line.match(/^###?\s*(.+)/);
    if (m) {
      const l = m[1].toLowerCase();
      if (l.includes('核心') || l.includes('core') || l.includes('overall')) cur = 'core';
      else if (l.includes('谈判') || l.includes('negotiat')) cur = 'negotiation';
      else if (l.includes('节奏') || l.includes('pacing') || l.includes('timing')) cur = 'pacing';
    } else if (cur && line.trim()) {
      strat[cur + '_en'] = (strat[cur + '_en'] || '') + ' ' + line.trim();
      strat[cur + '_zh'] = strat[cur + '_en'];
    }
  }
  if (Object.keys(strat).length === 0 && body.length < 1000) strat.core_en = strat.core_zh = body;
  analysis.strategy = strat;
}

function parseRisks(body) {
  const risks = [];
  const lines = body.split('\n');
  for (const line of lines) {
    const t = line.replace(/^[\s\-•*]+/, '').trim();
    if (!t) continue;
    let level = 'medium';
    if (t.match(/^(HIGH|高|[🔴🟥])/i)) level = 'high';
    else if (t.match(/^(LOW|低|[🟢🟩])/i)) level = 'low';
    const content = t.replace(/^(HIGH|MEDIUM|MED|LOW|高|中|低|[🔴🟡🟢🟥🟩])[：:\s\-]*/i, '').trim();
    if (content) risks.push({ level, content_en: content, content_zh: content });
  }
  return risks;
}

function parseDeliverable(analysis, body) {
  const dlv = {};
  const lines = body.split('\n');
  let inContent = false, contentLines = [];
  for (const line of lines) {
    const m = line.match(/^(?:\*\*)?(?:类型|type)[：:]?\s*(?:\*\*)?\s*(\w+)/i);
    if (m) { dlv.type = m[1].trim().toLowerCase(); continue; }
    const mc = line.match(/^(?:\*\*)?(?:内容|content|draft|正文)[：:]?\s*(?:\*\*)?\s*(.*)/i);
    if (mc) { inContent = true; if (mc[1]) contentLines.push(mc[1]); continue; }
    if (inContent) contentLines.push(line);
  }
  if (!dlv.content_en && body.length > 20) {
    const clean = body.replace(/^(?:\*\*)?(?:类型|type)[：:]\s*\w+[\s\n]*/i, '').trim();
    if (clean) dlv.content_en = dlv.content_zh = clean;
  } else if (contentLines.length > 0) {
    dlv.content_en = dlv.content_zh = contentLines.join('\n').trim();
  }
  if (dlv.type && !['email_template','meeting_agenda','negotiation_script','pitch_outline','none'].includes(dlv.type))
    dlv.type = 'email_template';
  if (dlv.content_en && !dlv.type) dlv.type = 'email_template';
  if (dlv.content_en || dlv.type) analysis.deliverable = dlv;
}

function callDeepSeek(systemPrompt, userPrompt, opts = {}) {
  const { temperature = 0.3, maxTokens = 4096, jsonMode = true } = opts;
  if (!CONFIG.DEEPSEEK_API_KEY) throw new Error('DEEPSEEK_API_KEY not configured');

  const messages = [];
  if (systemPrompt) messages.push({ role: 'system', content: systemPrompt });
  messages.push({ role: 'user', content: userPrompt });

  const body = {
    model: CONFIG.DEEPSEEK_MODEL,
    messages,
    temperature,
    max_tokens: maxTokens
  };
  if (jsonMode && CONFIG.DEEPSEEK_MODEL !== 'deepseek-chat') body.response_format = { type: 'json_object' };

  const t0 = Date.now();
  console.log(`deepseek call start: model=${CONFIG.DEEPSEEK_MODEL} max_tokens=${maxTokens} prompt_len=${systemPrompt.length + userPrompt.length}`);
  return fetch('https://api.deepseek.com/v1/chat/completions', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${CONFIG.DEEPSEEK_API_KEY}`
    },
    body: JSON.stringify(body)
  }).then(resp => {
    console.log(`deepseek response status: ${resp.status} in ${Date.now() - t0}ms`);
    if (!resp.ok) {
      return resp.text().then(t => { throw new Error(`DeepSeek ${resp.status}: ${t.substring(0, 200)}`); });
    }
    return resp.json();
  }).then(data => {
    const content = data.choices?.[0]?.message?.content;
    if (!content) { console.error('DeepSeek empty content'); return {}; }
    console.log(`deepseek ok: ${content.length} chars`);
    return parseJSON(content);
  }).catch(err => {
    console.error('deepseek fetch error:', err.message);
    return {};
  });
}

// Groq API call — OpenAI-compatible, fast, reliable JSON
async function callGroq(systemPrompt, userPrompt, opts = {}) {
  const { temperature = 0.3, maxTokens = 4096, jsonMode = true } = opts;
  if (!CONFIG.GROQ_API_KEY) return callDeepSeek(systemPrompt, userPrompt, opts);

  const messages = [];
  if (systemPrompt) messages.push({ role: 'system', content: systemPrompt });
  messages.push({ role: 'user', content: userPrompt });

  const body = {
    model: CONFIG.GROQ_MODEL,
    messages,
    temperature,
    max_tokens: maxTokens
  };
  if (jsonMode) body.response_format = { type: 'json_object' };

  const t0 = Date.now();
  console.log(`groq call start: model=${CONFIG.GROQ_MODEL} max_tokens=${maxTokens} prompt=${systemPrompt.length + userPrompt.length} hasKey=${!!CONFIG.GROQ_API_KEY}`);
  return fetch('https://api.groq.com/openai/v1/chat/completions', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${CONFIG.GROQ_API_KEY}`
    },
    body: JSON.stringify(body)
  }).then(resp => {
    console.log(`groq response status: ${resp.status} in ${Date.now() - t0}ms`);
    if (!resp.ok) return resp.text().then(t => { throw new Error(`Groq ${resp.status}: ${t.substring(0, 200)}`); });
    return resp.json();
  }).then(data => {
    const content = data.choices?.[0]?.message?.content;
    if (!content) { console.error('Groq empty content'); return {}; }
    console.log(`groq ok: ${content.length} chars`);
    const parsed = parseJSON(content);
    if (!parsed || Object.keys(parsed).length === 0) {
      console.error(`groq parseJSON failed. raw[0..300]: ${content.substring(0, 300)}`);
    }
    return parsed;
  }).catch(err => {
    console.error('groq error:', err.message, 'hasKey:', !!CONFIG.GROQ_API_KEY, 'keyLen:', (CONFIG.GROQ_API_KEY || '').length);
    return {};
  });
}

// ============================================================================
// TAVILY WEB SEARCH — Live intelligence retrieval
// ============================================================================
async function searchTavily(query) {
  if (!CONFIG.TAVILY_API_KEY) { console.log('tavily: no key configured'); return []; }
  console.log(`tavily search: "${query.substring(0,60)}"`);
  try {
    const resp = await fetch('https://api.tavily.com/search', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        api_key: CONFIG.TAVILY_API_KEY,
        query: query,
        search_depth: 'basic',
        max_results: 4,
        include_answer: false
      })
    });
    console.log(`tavily status: ${resp.status}`);
    if (!resp.ok) { console.error(`Tavily ${resp.status}`); return []; }
    const data = await resp.json();
    console.log(`tavily ok: ${(data.results||[]).length} results`);
    return (data.results || []).map(r => ({
      title: r.title,
      url: r.url,
      snippet: r.content || ''
    }));
  } catch (e) {
    console.error('tavily error:', e.message);
    return [];
  }
}

