const RULE_VEC_DIM = 500;

function cosineSimilarity(a,b){let dot=0,na=0,nb=0;for(let i=0;i<a.length;i++){dot+=a[i]*b[i];na+=a[i]*a[i];nb+=b[i]*b[i];}return na&&nb?dot/(Math.sqrt(na)*Math.sqrt(nb)):0;}
function searchRules(q,k){k=k||10;const w=(q.toLowerCase().match(/[a-z一-鿿]+/g)||[]);const t={};for(const x of w){if(dict[x]!==undefined)t[x]=(t[x]||0)+1;}const v=new Array(RULE_VEC_DIM).fill(0);for(const[x,c]of Object.entries(t)){const i=dict[x];const d=docf[x]||1;v[i]=(c/(w.length||1))*Math.log((RULE_VECTORS.length+1)/(d+1))+1;}const s=RULE_VECTORS.map(r=>({...r,_score:cosineSimilarity(v,r.vec)}));s.sort((a,b)=>b._score-a._score);return s.slice(0,k).filter(r=>r._score>0.1);}
