const rateLimit = new Map();
const RATE_LIMIT_WINDOW = 60000;
const RATE_LIMIT_MAX_REQUESTS = 20;

function checkRateLimit(ip) {
  const now = Date.now();
  const entry = rateLimit.get(ip);
  if (!entry) { rateLimit.set(ip, { count: 1, windowStart: now }); return true; }
  if (now - entry.windowStart > RATE_LIMIT_WINDOW) { entry.count = 1; entry.windowStart = now; return true; }
  entry.count++;
  if (entry.count > RATE_LIMIT_MAX_REQUESTS) return false;
  if (rateLimit.size > 1000) {
    for (const [k, v] of rateLimit) {
      if (now - v.windowStart > RATE_LIMIT_WINDOW) rateLimit.delete(k);
    }
  }
  return true;
}

// Active CORS origin — set per-request in main_handler
let activeCorsOrigin = 'https://onion-create.github.io';

// ============================================================================
// SCF ENTRY POINT (Tencent Cloud)
// ============================================================================
exports.main_handler = async (event, context) => {
  console.log('Fathom v5.8');
  let method, path, headers, body, clientIP;
  if (event.httpMethod) {
    method = event.httpMethod; path = event.path || '/'; headers = event.headers || {};
    body = event.body || ''; clientIP = event.requestContext?.sourceIp || 'unknown';
  } else {
    method = event.method || 'POST'; path = event.path || '/'; headers = event.headers || {};
    body = event.body || event.rawBody || ''; clientIP = 'unknown';
  }
  const env = {};
  if (event.environment) Object.assign(env, event.environment);
  if (event.secret) Object.assign(env, event.secret);
  if (globalThis._WORKER_ENV) Object.assign(env, globalThis._WORKER_ENV);
  if (typeof process !== 'undefined' && process.env) Object.assign(env, process.env);
  initWithEnv(env);
  const origin = headers['origin'] || headers['Origin'] || '';
  activeCorsOrigin = origin || activeCorsOrigin;
  const t0 = Date.now();
  if (method === 'OPTIONS') {
    return scfReply('', 204, { 'Access-Control-Allow-Origin': activeCorsOrigin, 'Access-Control-Allow-Methods': 'POST,OPTIONS', 'Access-Control-Allow-Headers': 'Content-Type' });
  }
  if (path.includes('/env') || path.includes('/ping')) return scfReply(JSON.stringify({ status: 'ok', mode: 'v5.8', has_deepseek: !!CONFIG.DEEPSEEK_API_KEY, has_tavily: !!CONFIG.TAVILY_API_KEY, key_len: (CONFIG.TAVILY_API_KEY||'').length }));

  if (path.includes('/simulate')) {
    try {
      const simBody = typeof body === 'string' ? JSON.parse(body) : body;
      return scfReply(JSON.stringify(await runSimulation(simBody)));
    } catch(e) { return scfReply(JSON.stringify({ error: e.message }), 500); }
  }

  if (path.includes('/supplement')) {
    try {
      const supBody = typeof body === 'string' ? JSON.parse(body) : body;
      return scfReply(JSON.stringify(await supplementAnalysis(supBody)));
    } catch(e) { return scfReply(JSON.stringify({ error: e.message }), 500); }
  }

  if (path.includes('/compare')) {
    try {
      const cmpBody = typeof body === 'string' ? JSON.parse(body || '{}') : (body || {});
      const { countryA, countryB } = cmpBody;
      if (!countryA || !countryB) return scfReply(JSON.stringify({ error: 'Missing countryA or countryB' }), 400);

      function getDataTier(code) {
        const hasHofstede = !!(HOFSTEDE_DB[code] && Object.keys(HOFSTEDE_DB[code]).length >= 6);
        const hasRules = !!(CULTURAL_DB[code] && (CULTURAL_DB[code].rules || []).length > 0);
        if (hasHofstede && hasRules) return 'verified';
        if (hasHofstede || hasRules) return 'research-backed';
        return 'ai-analysis';
      }
      function getCountryInfo(code) {
        const cd = CULTURAL_DB[code] || {};
        const hd = HOFSTEDE_DB[code] || {};
        const gd = GLOBE_DB[code] || null;
        const td = TROMPENAARS_DB[code] || null;
        return {
          name: cd.en || code, name_zh: cd.zh || code, flag: cd.flag || '',
          data_tier: getDataTier(code),
          hofstede: hd, globe: gd, trompenaars: td,
          rules_count: (cd.rules || []).length
        };
      }
      return scfReply(JSON.stringify({
        country_a: getCountryInfo(countryA),
        country_b: getCountryInfo(countryB),
        version: '5.8.0'
      }));
    } catch(e) { return scfReply(JSON.stringify({ error: e.message }), 500); }
  }

  try {
    const reqBody = typeof body === 'string' ? JSON.parse(body || '{}') : (body || {});
    const { scenario, message } = reqBody;
    if (message) return scfReply(JSON.stringify({ evaluation: await evaluateMessage(message) }));
    if (!scenario) return scfReply(JSON.stringify({ error: 'Missing scenario' }), 400);

    const countryCode = detectCountry(scenario);

    // AI-only fallback: country not in our database — use DeepSeek general knowledge
    if (!countryCode) {
      const aiResult = await analyzeUnknownCountry(scenario, t0);
      return scfReply(JSON.stringify(aiResult));
    }

    // Also route to AI-only if detected but no structured data available
    const cd = CULTURAL_DB[countryCode];
    if (!cd) {
      const aiResult = await analyzeUnknownCountry(scenario, t0);
      return scfReply(JSON.stringify(aiResult));
    }

    // Build cultural data using CULTURAL_DB
    const culturalData = cd ? {
      country_code: countryCode,
      primary_country_data: { name: cd.en, name_zh: cd.zh, flag: cd.flag, profile: cd.profile, profile_zh: cd.profile_zh || '', region: cd.region, data_tier: cd.data_tier || 'ai_generated' },
      hofstede_data: HOFSTEDE_DB[countryCode] || {},
      globe_data: GLOBE_DB[countryCode] || null,
      trompenaars_data: TROMPENAARS_DB[countryCode] || null,
      matched_rules: cd.rules || []
    } : (() => {
      // Fallback for countries not yet in CULTURAL_DB: use detectCountry Hofstede + RULE_VECTORS
      const patterns = {
        cn: { en:'China', zh:'中国', flag:'🇨🇳' }, jp: { en:'Japan', zh:'日本', flag:'🇯🇵' },
        kr: { en:'South Korea', zh:'韩国', flag:'🇰🇷' }, de: { en:'Germany', zh:'德国', flag:'🇩🇪' },
        ru: { en:'Russia', zh:'俄罗斯', flag:'🇷🇺' }, sg: { en:'Singapore', zh:'新加坡', flag:'🇸🇬' },
        in: { en:'India', zh:'印度', flag:'🇮🇳' }, br: { en:'Brazil', zh:'巴西', flag:'🇧🇷' },
        ae: { en:'UAE', zh:'阿联酋', flag:'🇦🇪' }, sa: { en:'Saudi Arabia', zh:'沙特', flag:'🇸🇦' },
        gb: { en:'UK', zh:'英国', flag:'🇬🇧' }, us: { en:'USA', zh:'美国', flag:'🇺🇸' },
        fr: { en:'France', zh:'法国', flag:'🇫🇷' }, au: { en:'Australia', zh:'澳大利亚', flag:'🇦🇺' },
        ca: { en:'Canada', zh:'加拿大', flag:'🇨🇦' }, mx: { en:'Mexico', zh:'墨西哥', flag:'🇲🇽' },
        it: { en:'Italy', zh:'意大利', flag:'🇮🇹' }, es: { en:'Spain', zh:'西班牙', flag:'🇪🇸' },
        nl: { en:'Netherlands', zh:'荷兰', flag:'🇳🇱' }, se: { en:'Sweden', zh:'瑞典', flag:'🇸🇪' },
        ch: { en:'Switzerland', zh:'瑞士', flag:'🇨🇭' }, tr: { en:'Turkey', zh:'土耳其', flag:'🇹🇷' },
        eg: { en:'Egypt', zh:'埃及', flag:'🇪🇬' }, za: { en:'South Africa', zh:'南非', flag:'🇿🇦' },
        ng: { en:'Nigeria', zh:'尼日利亚', flag:'🇳🇬' }, id: { en:'Indonesia', zh:'印度尼西亚', flag:'🇮🇩' },
        vn: { en:'Vietnam', zh:'越南', flag:'🇻🇳' }, th: { en:'Thailand', zh:'泰国', flag:'🇹🇭' },
        my: { en:'Malaysia', zh:'马来西亚', flag:'🇲🇾' }, ph: { en:'Philippines', zh:'菲律宾', flag:'🇵🇭' },
        pl: { en:'Poland', zh:'波兰', flag:'🇵🇱' }, ar: { en:'Argentina', zh:'阿根廷', flag:'🇦🇷' },
        cl: { en:'Chile', zh:'智利', flag:'🇨🇱' }, bd: { en:'Bangladesh', zh:'孟加拉国', flag:'🇧🇩' },
        pt: { en:'Portugal', zh:'葡萄牙', flag:'🇵🇹' }, ie: { en:'Ireland', zh:'爱尔兰', flag:'🇮🇪' },
        fi: { en:'Finland', zh:'芬兰', flag:'🇫🇮' }, il: { en:'Israel', zh:'以色列', flag:'🇮🇱' },
        nz: { en:'New Zealand', zh:'新西兰', flag:'🇳🇿' }, hk: { en:'Hong Kong', zh:'中国香港', flag:'🇭🇰' },
      };
      const pi = patterns[countryCode] || { en: countryCode, zh: countryCode, flag: '🌍' };
      const matchedRules = (typeof searchRules === 'function')
        ? searchRules(scenario, 6).map(r => ({ cat: r.cat || '', rule: { en: r.rule?.en || '', zh: r.rule?.zh || '' }, _score: r._score }))
        : [];
      // Pull profile from CULTURAL_DB if available, else from COUNTRY_DATA via detectCountry lookup
      const cdbProfile = (CULTURAL_DB[countryCode] && CULTURAL_DB[countryCode].profile) || '';
      const cdbProfileZh = (CULTURAL_DB[countryCode] && CULTURAL_DB[countryCode].profile_zh) || (CULTURAL_DB[countryCode] && CULTURAL_DB[countryCode].profile) || '';
      const cdbRegion = (CULTURAL_DB[countryCode] && CULTURAL_DB[countryCode].region) || '';
      return {
        country_code: countryCode,
        primary_country_data: {
          name: pi.en, name_zh: pi.zh, flag: pi.flag,
          profile: cdbProfile, profile_zh: cdbProfileZh,
          region: cdbRegion || pi.region || '',
          data_tier: (CULTURAL_DB[countryCode] && CULTURAL_DB[countryCode].data_tier) || 'ai_generated'
        },
        hofstede_data: HOFSTEDE_DB[countryCode] || {},
        globe_data: GLOBE_DB[countryCode] || null,
        trompenaars_data: TROMPENAARS_DB[countryCode] || null,
        matched_rules: matchedRules
      };
    })();

    const aiAnalysis = await analyzeScenario(scenario, culturalData);

    // Generate dialogue snippets for known countries (fast, lightweight)
    const snippets = await generateDialogueSnippets(scenario, countryCode, aiAnalysis?.analysis || {});
    if (snippets && snippets.length > 0 && aiAnalysis?.analysis) {
      aiAnalysis.analysis.dialogue_snippets = snippets;
    }

    return scfReply(JSON.stringify({
      pipeline: { version: '5.8.0', ms: Date.now() - t0 },
      country_code: countryCode,
      cultural_data: culturalData,
      ai_analysis: aiAnalysis
    }));
  } catch (err) {
    return scfReply(JSON.stringify({ error: err.message }), 500);
  }
};
// Helper: SCF response format
function scfReply(bodyStr, status, extraHeaders) {
  const h = extraHeaders || {};
  h['Content-Type'] = 'application/json';
  h['Access-Control-Allow-Origin'] = activeCorsOrigin;
  return { statusCode: status || 200, headers: h, body: bodyStr };
}

// Helper: Response class for internal use
class Response {
  constructor(body, opts = {}) {
    this.body = body;
    this.status = opts.status || 200;
    this.headers = new Map(Object.entries(opts.headers || {}));
  }
}

// Helper: Headers
class Headers {
  constructor(init = {}) { this._headers = init; }
  get(k) { return this._headers[k.toLowerCase()] || ''; }
  forEach(fn) { for (const [k, v] of Object.entries(this._headers)) fn(v, k); }
}

class Request {
  constructor(url, opts = {}) {
    this.url = url;
    this.method = opts.method || 'GET';
    this.headers = new Headers(opts.headers || {});
    this._body = opts.body;
  }
  async json() { return JSON.parse(this._body || '{}'); }
}

// ============================================================================
// SIMULATION — Interactive conversation practice with cultural feedback
// ============================================================================
async function runSimulation(body) {
  const {
    scenario, scene_context, cultural_rules, user_message,
    conversation_round, conversation_history, counterpart_persona
  } = body;

  const historyText = (conversation_history || []).map(h =>
    `Round ${h.round}: User said "${h.user}" → Counterpart replied "${h.counterpart}"`
  ).join('\n');

  const prompt = `You are evaluating a user's message in a cross-cultural business simulation.

SCENARIO: ${scenario || 'Cross-cultural business meeting'}

COUNTERPART: ${counterpart_persona || 'business counterpart'}
CULTURAL CONTEXT: ${JSON.stringify(cultural_rules || [])}

CONVERSATION HISTORY:
${historyText || '(First message — no history yet)'}

USER'S MESSAGE (Round ${conversation_round || 1}): "${user_message}"

Evaluate the user's cross-cultural communication. Return ONLY valid JSON:
{
  "conversation_round": ${conversation_round || 1},
  "simulation": {
    "scores": {
      "cultural_appropriateness": { "score": 7, "comment_en": "...", "comment_zh": "..." },
      "effectiveness": { "score": 6, "comment_en": "...", "comment_zh": "..." },
      "politeness_and_face": { "score": 8, "comment_en": "...", "comment_zh": "..." },
      "language_quality": { "score": 7, "comment_en": "...", "comment_zh": "..." }
    },
    "improvements": [
      { "type": "positive", "what_you_did_en": "...", "what_you_did_zh": "...", "why_it_matters_en": "...", "why_it_matters_zh": "..." },
      { "type": "warning", "what_you_did_en": "...", "what_you_did_zh": "...", "why_it_matters_en": "...", "why_it_matters_zh": "...", "better_phrasing_en": "...", "better_phrasing_zh": "..." }
    ],
    "cultural_insight_en": "Deep insight about the cultural dynamics at play",
    "cultural_insight_zh": "深入了解当前文化动态",
    "counterpart_response": "How the counterpart would actually reply (in English)",
    "counterpart_response_zh": "对方可能的中文回应"
  }
}

SCORING: Each dimension 1-10. Be honest — do not inflate scores.
- cultural_appropriateness: Does this respect the counterpart's cultural norms?
- effectiveness: Will this achieve the user's business goal?
- politeness_and_face: Does this preserve face and hierarchy?
- language_quality: Is the language clear, appropriate, and professional?

IMPROVEMENTS: 2-4 items. Mix positive and constructive feedback. Include better_phrasing for warnings.`;

  let result = await callDeepSeek(
    'You are an expert cross-cultural communication coach. Evaluate messages honestly — be constructive but direct. Output valid JSON.',
    prompt,
    { temperature: 0.4, maxTokens: 4096, jsonMode: true }
  );

  // Retry once if simulation data is missing (API glitch)
  if (!result.simulation || !result.simulation.scores) {
    console.log('simulate retry: first call returned incomplete data, retrying...');
    result = await callDeepSeek(
      'You are an expert cross-cultural communication coach. Output ONLY valid JSON.',
      prompt,
      { temperature: 0.5, maxTokens: 4096, jsonMode: true }
    );
  }

  // If still no simulation, return a clear error the frontend can handle
  if (!result.simulation || !result.simulation.scores) {
    return {
      error: 'simulation_generation_failed',
      error_zh: '模拟反馈生成失败，请重试',
      error_en: 'Simulation feedback generation failed. Please try again.'
    };
  }

  return result;
}

// ============================================================================
// EVALUATE — Simple message evaluation (legacy simulation mode)
// ============================================================================
async function evaluateMessage(message) {
  const prompt = `Evaluate this message in the context of cross-cultural business communication:

MESSAGE: "${message}"

Return ONLY valid JSON:
{
  "evaluation": {
    "score": 7,
    "good": "What was appropriate or effective (English)",
    "good_zh": "做得好的地方（中文）",
    "watchOut": "What to be careful about (English)",
    "watchOut_zh": "需要注意的地方（中文）",
    "critical": "Critical issue if any (English, or empty string)",
    "critical_zh": "关键问题（中文，没有则为空）",
    "betterVersion": {
      "native": "Original language improved version",
      "english": "English improved version",
      "chinese": "中文改进版"
    }
  }
}

Score 1-10 on cultural appropriateness. Be specific and actionable.`;

  return callDeepSeek(
    'You are a cross-cultural communication evaluator. Score honestly, give specific feedback. Output valid JSON.',
    prompt,
    { temperature: 0.3, maxTokens: 2048, jsonMode: true }
  );
}

// ============================================================================
// FOLLOW-UP HELPERS — Worker-side fallback when Agent A under-asks
// ============================================================================

// Risk keyword patterns that should always trigger follow-up questions
const RISK_KEYWORDS = {
  contract: ['合同', 'contract', 'agreement', '合约', '协议'],
  dispute: ['纠纷', '违约', '拒收', 'dispute', 'breach', 'wrongful', 'refused', 'sold to other', '转卖'],
  payment: ['付款', '支付', '欠款', '信用证', 'payment', 'invoice', 'lc ', 'l/c', 'transfer'],
  quality: ['质量', '检验', '验收', 'quality', 'inspection', 'survey', '拒货'],
  legal: ['仲裁', '诉讼', '法院', '管辖', 'arbitration', 'litigation', 'court', 'jurisdiction'],
  relationship: ['首次', '老客户', 'new client', 'first time', 'long term', '长期'],
};

// Heuristically infer what level of follow-up is needed based on scenario content
function inferRiskLevel(scenario) {
  const lower = (scenario || '').toLowerCase();
  let score = 0;
  for (const cat in RISK_KEYWORDS) {
    if (RISK_KEYWORDS[cat].some(kw => lower.indexOf(kw.toLowerCase()) !== -1)) score += 2;
  }
  // High-value keywords
  if (/[\d,]{6,}|million|billion|usd|cny|rmb|rmb|万|百万|亿/i.test(scenario)) score += 2;
  // Disputes and contracts are highest priority
  if (/dispute|breach|违约|纠纷|breach of contract/i.test(scenario)) score += 3;
  return score; // 0 = info only, 3+ = needs questions
}

function inferGapSummary(scenario, sceneAnalysis) {
  const country = sceneAnalysis?.scene_graph?.primary_country?.name || '';
  const stage = sceneAnalysis?.scene_graph?.interaction_stage || '';
  if (country) {
    const en = `To give you the most precise strategy for dealing with your ${country} counterpart, I want to understand a few key details about your situation.`;
    const zh = `为了给您最贴合实际情况的策略，我需要了解几个关键细节。`;
    return { en, zh };
  }
  return { en: 'I need a few key details to give you the most precise strategy.', zh: '我需要了解几个关键细节，以给出最精准的策略。' };
}

// If Agent A didn't generate questions, build a small targeted set based on
// which risk patterns matched. Always in zh + en, multiple-choice.
function generateFallbackFollowUps(scenario, sceneAnalysis) {
  const lower = (scenario || '').toLowerCase();
  const country = sceneAnalysis?.scene_graph?.primary_country?.code || '';
  const matched = {
    contract: RISK_KEYWORDS.contract.some(k => lower.indexOf(k.toLowerCase()) !== -1),
    dispute: RISK_KEYWORDS.dispute.some(k => lower.indexOf(k.toLowerCase()) !== -1),
    payment: RISK_KEYWORDS.payment.some(k => lower.indexOf(k.toLowerCase()) !== -1),
    quality: RISK_KEYWORDS.quality.some(k => lower.indexOf(k.toLowerCase()) !== -1),
    legal: RISK_KEYWORDS.legal.some(k => lower.indexOf(k.toLowerCase()) !== -1),
  };

  // Detect industry context for specialized question variants
  let industry = null;
  const industryKeywords = {
    petroleum: ['diesel', 'crude', 'oil', 'refinery', 'fuel', 'lng', 'lpg', '炼油', '柴油', '原油'],
    electronics: ['electronic', 'semiconductor', 'chip', 'circuit', 'component', '电子', '芯片', '半导体', '元器件'],
    pharma: ['pharma', 'drug', 'api ', 'vaccine', 'fda', 'gmp', '制药', '药品', '疫苗'],
    automotive: ['car', 'vehicle', 'ev ', 'auto parts', '汽车', '车辆', '电动车', '零部件'],
  };
  for (const [ind, kws] of Object.entries(industryKeywords)) {
    if (kws.some(k => lower.indexOf(k) !== -1)) { industry = ind; break; }
  }

  const questions = [];

  if (matched.dispute) {
    questions.push({
      id: 'q_dispute_position',
      question_zh: '纠纷中对方已采取的下一步行动是什么？',
      question_en: 'What has the counterpart already done since the dispute began?',
      why_zh: '这决定了你下一步的法律策略。无回复意味着你需要单方面施压；主动提议补偿说明他们有谈判空间；发出反索赔则可能需要进入正式争端解决程序。',
      why_en: 'Determines your legal strategy: silence = unilateral pressure needed, compensation offer = negotiation space, counterclaim = formal dispute resolution.',
      options: [
        { value: 'no_response', label_zh: '完全无回复或回避', label_en: 'No response or avoidance' },
        { value: 'claimed_force_majeure', label_zh: '主张不可抗力或运营问题', label_en: 'Cited force majeure or operational issues' },
        { value: 'offered_compensation', label_zh: '主动提议补偿或折扣', label_en: 'Offered partial compensation or discount' },
        { value: 'threatened', label_zh: '发出法律威胁或反索赔', label_en: 'Issued legal threats or counterclaims' },
      ],
    });
  }

  if (matched.contract) {
    questions.push({
      id: 'q_governing_law',
      question_zh: industry === 'petroleum'
        ? '合同中约定的货物所有权转移时点（title transfer）和争议解决条款是什么？'
        : '合同中约定的争议解决条款是什么？',
      question_en: industry === 'petroleum'
        ? 'What does your contract specify for title transfer timing and dispute resolution?'
        : 'What does your contract specify for dispute resolution?',
      why_zh: industry === 'petroleum'
        ? '油品贸易中货权转移时点是一切纠纷的核心。罐对罐交货、FOB还是CIF，直接决定了炼厂是否有权转卖。SIAC还是HKIAC决定了你冻结对方资产的路径和速度。'
        : '争议解决条款决定了你能在哪维权、用多久、花多少钱。SIAC/HKIAC/ICC在临时保全措施的速度上差别显著。',
      why_en: 'Dispute resolution clause defines where, how fast, and at what cost you can enforce your rights. SIAC/HKIAC/ICC differ significantly in interim relief speed.',
      options: [
        { value: 'local_court', label_zh: '本地法院诉讼', label_en: 'Local court litigation' },
        { value: 'intl_arbitration', label_zh: '国际仲裁（如 SIAC、HKIAC、ICC）', label_en: 'International arbitration (SIAC/HKIAC/ICC)' },
        { value: 'unclear', label_zh: '条款不明确或缺失', label_en: 'Clause is unclear or missing' },
        { value: 'not_signed', label_zh: '尚未签署正式合同', label_en: 'No formal contract signed' },
      ],
    });
  }

  if (matched.payment || matched.dispute) {
    const isPetro = industry === 'petroleum';
    questions.push({
      id: 'q_payment_stage',
      question_zh: isPetro
        ? '资金和单证目前处于哪个阶段？（已开信用证？已付款？）'
        : '资金/单证目前处于哪个阶段？',
      question_en: isPetro
        ? 'What is the current status of payment, LC, and documents?'
        : 'What is the current stage of payment/documents?',
      why_zh: isPetro
        ? '信用证条款和单证瑕疵是油品贸易中最常见的拒付理由。你需要告诉我LC是否仍有效、发票是否议付、提单是否在你手中——这三个事实会直接决定你的法律立场。'
        : '支付状态决定了你的谈判筹码。已付款意味着你需要追偿，未付款意味着你有保留履约的杠杆。',
      why_en: isPetro
        ? 'LC terms and documentary compliance are the most common grounds for non-payment in petroleum. Whether the LC is still valid, whether documents were negotiated, and who holds the B/L directly determines your legal standing.'
        : 'Payment status defines your leverage: paid = pursuing recovery, unpaid = you can withhold performance.',
      options: [
        { value: 'not_paid', label_zh: '尚未付款，等交货后付', label_en: 'Not yet paid (paid on delivery)' },
        { value: 'paid_full', label_zh: '已全额付款', label_en: 'Fully paid' },
        { value: 'lc_unused', label_zh: '信用证已开但未使用', label_en: 'LC issued but unused' },
        { value: 'partial', label_zh: '已预付定金', label_en: 'Partial deposit paid' },
      ],
    });
  }

  if (matched.quality) {
    questions.push({
      id: 'q_quality_doc',
      question_zh: '您手上的书面证据状态？',
      question_en: 'What written evidence do you currently have?',
      why_zh: '跨境纠纷中书面证据的质量直接决定胜率。有完整单证和检验报告意味着你有强证据链；只有邮件或聊天记录则需要更复杂的证据开示程序。',
      why_en: 'Quality of written evidence directly determines case strength. Complete documents + survey report = strong chain; only emails/chats = complex discovery needed.',
      options: [
        { value: 'full_docs', label_zh: '完整合同+全套单证+检验报告', label_en: 'Full contract + complete documents + survey report' },
        { value: 'partial', label_zh: '仅有部分邮件/聊天记录', label_en: 'Only partial email/chat records' },
        { value: 'third_party', label_zh: '有第三方机构出具的认证', label_en: 'Third-party inspection certificate available' },
        { value: 'minimal', label_zh: '仅口头沟通无书面证据', label_en: 'Mostly verbal, minimal written evidence' },
      ],
    });
  }

  if (matched.legal) {
    questions.push({
      id: 'q_local_presence',
      question_zh: '对方在该地（交易地/注册地）是否有可见资产？',
      question_en: 'Does the counterpart have visible assets in the relevant jurisdiction?',
      why_zh: '强制执行的第一步是可执行资产。如果对方只有离岸账户而没有当地实体，你的冻结令和判决可能只是一纸空文。必须先确认资产存在才能制定法律策略。',
      why_en: 'Enforcement starts with enforceable assets. Offshore-only counter-parties make freezing orders and judgments unenforceable. Asset tracing must precede legal strategy.',
      options: [
        { value: 'local_entity', label_zh: '在当地有正式注册公司', label_en: 'Local registered company' },
        { value: 'only_offshore', label_zh: '只有离岸账户/无本地资产', label_en: 'Offshore accounts only / no local assets' },
        { value: 'shipment_in_transit', label_zh: '货物目前在运输途中可追踪', label_en: 'Goods currently in transit and traceable' },
        { value: 'unknown', label_zh: '不清楚', label_en: 'Not sure' },
      ],
    });
  }

  // Always include a "your role" question if any risk pattern matched
  if (questions.length > 0 && questions.length < 4) {
    questions.push({
      id: 'q_your_role',
      question_zh: '您在本次纠纷中的角色是？',
      question_en: 'What is your role in this situation?',
      why_zh: '决策人、执行人和顾问在处理纠纷时的话语权和谈判策略完全不同。决策人可以立即承诺和解条件，执行人需要向上汇报的缓冲时间。了解角色可以帮助我给出匹配你实时行动能力的建议。',
      why_en: 'Decision-makers, implementers, and advisors have different mandates and negotiation strategies. Knowing your role ensures advice matches your authority to act.',
      options: [
        { value: 'principal', label_zh: '公司决策人/老板', label_en: 'Decision-maker / Principal' },
        { value: 'manager', label_zh: '部门负责人/项目经理', label_en: 'Department head / Project manager' },
        { value: 'staff', label_zh: '执行团队成员', label_en: 'Implementation team member' },
        { value: 'advisor', label_zh: '代表他人处理', label_en: 'Representing someone else' },
      ],
    });
  }

  // Cap at 4 most relevant
  return questions.slice(0, 4);
}
